using UnityEngine;using UnityEngine.AI;using System.IO;using System.Collections;
public class ObjectiveTrailProbe:MonoBehaviour{
 [System.Serializable]public class Stop{public string name;public Vector3 target,approach;}
 public Stop[] stops;
 IEnumerator Start(){string e=Path.GetFullPath("Evidence/objective-trails-20261030/");var a=GetComponent<NavMeshAgent>();var m=GetComponent<DemoMovement>();var cam=m.viewCamera;var follow=cam.GetComponent<DemoCamera>();File.WriteAllText(e+"playmode.txt","Unity="+Application.unityVersion+" scene="+gameObject.scene.name+"; direct navigation/teleport visual review, not keyboard walkthrough.\n");yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot(e+"spawn.png");foreach(var stop in stops){m.TakeManualControl();bool warp=a.Warp(stop.approach);a.SetDestination(stop.target);yield return new WaitForSeconds(.3f);float timeout=Time.time+6;while(a.pathPending||(a.remainingDistance>1.0f&&Time.time<timeout))yield return null;yield return new WaitForSeconds(.8f);File.AppendAllText(e+"playmode.txt",stop.name+" warp="+warp+" path="+a.pathStatus+" remaining="+a.remainingDistance+" position="+transform.position+" target="+stop.target+"\n");ScreenCapture.CaptureScreenshot(e+stop.name+"_gameplay.png");yield return new WaitForSeconds(.3f);if(follow)follow.enabled=false;cam.transform.position=stop.target+new Vector3(-3,6,-7);cam.transform.LookAt(stop.target);yield return new WaitForSeconds(.2f);ScreenCapture.CaptureScreenshot(e+stop.name+"_detail.png");yield return new WaitForSeconds(.2f);if(follow)follow.enabled=true;}File.AppendAllText(e+"playmode.txt","tour complete\n");}
}
